      "card_ids": ["C25","C31","C36","C33","C37","C38"]
    },
    {
      "claim": "L5 gut-wall efflux/intestinal metabolism records show naloxone and oxycodone are high-permeability non-efflux substrates in Caco-2 (C74, C66), and morphine is low-permeability but transported (C73) and an uptake-transporter substrate (C65); these are tertiary-amine morphinans or unrelated flavonoids, not the quaternary query, so they do not provide affirmative evidence for query F >= 20%.",
      "card_ids": ["C74","C66","C73","C65","C70"]
    },
    {
      "claim": "The high-F contexts (pethidine F 0.48-0.57, ~50%; rat EC 31-39%) are not transferable because pethidine is a small lipophilic tertiary amine ester lacking the quaternary ammonium charge and phenolic first-pass liabilities, and the rat EC values are species/formulation-specific.",
      "card_ids": ["C05","C06","C10","C18","C30","C26","C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
